const costKey=flights.some(f=>Number.isFinite(f.partialTotal))?'partialTotal':'price',timeKey=flights.some(f=>Number.isFinite(f.combinedDuration))?'combinedDuration':'duration';
const sort=$('sortFlights');sort.add(new Option('Best value','balance'));
