const tabbar=document.createElement('div');tabbar.className='result-tabs';const recommendations=tabs.map(([name,key])=>({name,key,best:[...flights].filter(f=>Number.isFinite(f[key])).sort((a,b)=>a[key]-b[key])[0]}));const cheapest=recommendations[0].best;tabbar.innerHTML=recommendations.map(({name,key,best})=>{const priced=best&&Number.isFinite(cost(best)),mins=best&&(Number.isFinite(time(best))?time(best):best.duration);const reason=key==='balance'?'A balance of price and travel time':key===timeKey?'Shortest '+(timeKey==='combinedDuration'?'outbound flight + round-trip road time':'outbound flight'):'Lowest '+(costKey==='partialTotal'?'estimated airfare + airport transport':'airfare quote');return `<button type="button" data-sort="${key}" data-index="${flights.indexOf(best)}" ${best?'':'disabled'}><span>${name}</span><strong>${best?(priced?money(cost(best)):money(best.price)+' airfare'):'Unavailable'}</strong><small>${best?esc(best.departure.id)+' → '+esc(best.arrival.id)+' · '+duration(mins)+' comparison time':'Not enough pricing information'}</small><small>${reason}</small><small>${priced?esc(best.selected.name)+' · '+money(best.selected.cost)+' estimated transport':''}</small><small>${best?'View journey →':''}</small></button>`;}).join('');const recHeading=document.createElement('h3');recHeading.textContent='Top recommendations';recHeading.className='recommend-heading';sort.closest('.sortbar').before(recHeading,tabbar);
const allHeading=document.createElement('h3');allHeading.textContent='All flight options';allHeading.className='recommend-heading';sort.closest('.sortbar').before(allHeading);const layout=document.createElement('div');layout.className='results-layout';list.before(layout);layout.innerHTML=`<aside class="filters"><h3>Filters</h3><label for="filterAirline">Airline</label><select id="filterAirline"><option value="">All airlines</option>${opts(airlines)}</select><label for="filterAirport">Departure airport</label><select id="filterAirport"><option value="">All airports</option>${opts(dep)}</select><label for="filterStops">Stops</label><select id="filterStops"><option value="">Any</option><option value="0">Nonstop</option><option value="1">Up to 1 stop</option></select><label for="filterMode">Airport transport</label><select id="filterMode"><option value="">Any</option><option>Drive and park</option><option>Drop-off and pickup</option><option>Uber / Lyft</option></select><label class="check-filter"><input type="checkbox" id="filterBudget" ${adults!==1?'disabled':''}> Within budget (known costs)</label><button type="button" id="clearFilters">Reset filters</button></aside><div class="results-main"><p id="resultCount" class="result-count"></p></div>`;layout.querySelector('.results-main').append(list);
function stamp(v){const [d,t]=String(v||'').split(/[ T]/);if(!t)return esc(v||'—');const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
