function render(){const key=sort.value;tabbar.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sort===key)));const mode=$('filterMode').value;const selected=f=>mode?f.options.find(o=>o.name===mode):f.selected;const subtotal=f=>{const o=selected(f);return adults===1&&Number.isFinite(o?.total)?o.total:Infinity;};const rank=f=>key==='partialTotal'&&mode?(selected(f)?.total??Infinity):f[key]??Infinity;let sorted=flights.filter(f=>(!$('filterAirline').value||(f.airlines||[]).includes($('filterAirline').value))&&(!$('filterAirport').value||f.departure.id===$('filterAirport').value)&&($('filterStops').value===''||f.stops<=Number($('filterStops').value))&&(!mode||selected(f))&&(!$('filterBudget').checked||subtotal(f)<=budget)).sort((a,b)=>rank(a)-rank(b)||a.price-b.price);const count=flights.length;$('resultCount').textContent=sorted.length+' of '+count+' flights';list.innerHTML=sorted.map(f=>{const g=ground.get(f.departure.id),o=selected(f),total=subtotal(f);return `<article class="flight-result"><header class="flight-heading"><div class="carrier">${logo(f)}<div><strong>${esc((f.airlines||[]).join(' / '))}</strong><small>${esc(f.type||'Round trip')} · Outbound shown</small></div></div><div class="airfare-label">Round-trip fare <strong>${money(f.price)}</strong></div></header><div class="timeline"><div><strong>${stamp(f.departure.time)}</strong><span>${esc(f.departure.id)} · ${esc(f.departure.name||'')}</span><small>${shortDate(f.departure.time)}</small></div><div class="flight-track"><small>${duration(f.duration)}</small><div class="track-line"><i></i></div><small>${f.stops===0?'Nonstop':esc(f.stops)+(f.stops===1?' stop':' stops')}</small></div><div><strong>${stamp(f.arrival.time)}</strong><span>${esc(f.arrival.id)} · ${esc(f.arrival.name||'')}</span><small>${shortDate(f.arrival.time)}</small></div></div><details class="itinerary"><summary>Flight details</summary>${flightDetails(f)}<small>All flight times local to each airport. Return itinerary not retrieved.</small></details><section class="airport-comparison"><header><strong>Airport transportation</strong><span>Round trip</span></header>${f.options.map(x=>`<div class="airport-option"><span>${esc(x.name)}${x===o&&!overlap(x,f.options)&&Number.isFinite(x.cost)&&f.options.every(y=>Number.isFinite(y.cost))?' <small>Lowest estimate</small>':''}</span><strong>${x.low!=null?money(x.low)+'–'+money(x.high):Number.isFinite(x.cost)?money(x.cost):'Price unavailable'}</strong></div>`).join('')}<div class="airport-option"><span>Bus / train</span><span>Fare unavailable</span></div>${o&&overlap(o,f.options)?'<p>Some options have similar costs.</p>':''}</section><footer class="result-total polished-total"><div><small>${Number.isFinite(total)?'Estimated flight + airport transport':'Round-trip airfare'}</small><strong class="total-number">${money(Number.isFinite(total)?total:f.price)}</strong><small>${Number.isFinite(total)?'Includes '+esc(o.name)+' estimate':'Transportation not included'}</small></div><button type="button" class="pick-flight" data-index="${flights.indexOf(f)}">Select flight</button></footer></article>`;}).join('')||'<div class="empty">No results match these filters.</div>';}
