// Transit prototype: one explicit request per airport/date/time, cached in this page.
const transitCache = new Map();
async function transitPreview(button,origin,airportCode,date,flightTime,returnAirport,returnTime){
 const target=button.nextElementSibling;button.disabled=true;target.textContent='Looking up scheduled transit in both directions…';
 async function direction(code,time,back){try{const n=await nearby(origin),airport=(await airportData()).find(a=>a.code===code),zone=airportZone(code);if(!airport||!zone)throw Error('Airport not supported');const flight=localInstant(time,zone);if(!Number.isFinite(flight))throw Error('Flight time unavailable');const limit=flight+(back?1:-3)*3600000,city=`${n.city.latitude},${n.city.longitude}`,air=`${airport.lat},${airport.lon}`;const q=new URLSearchParams({fromPlace:back?air:city,toPlace:back?city:air,time:new Date(limit).toISOString(),searchWindow:'43200',arriveBy:String(!back)}),key=q.toString();if(!transitCache.has(key))transitCache.set(key,fetch('https://api.transitous.org/api/v6/plan?'+key,{signal:AbortSignal.timeout(25000)}).then(r=>{if(!r.ok)throw Error('Transit unavailable');return r.json();}).catch(e=>{transitCache.delete(key);throw e;}));const data=await transitCache.get(key);const routes=(data.itineraries||[]).filter(x=>x.legs?.some(l=>/BUS|RAIL|TRAIN|SUBWAY|TRAM|TRANSIT|COACH|METRO/.test(l.mode))).filter(x=>back?Date.parse(x.startTime)>=limit:Date.parse(x.endTime)<=limit).slice(0,3);return `<p class="transit-note">${back?'Leave airport after':'Arrive at airport by'} ${localClock(limit,zone,true)} · fares unknown</p>`+(routes.length?routes.map(x=>`<section class="transit-route"><header><strong>${localClock(x.startTime,zone,true)} – ${localClock(x.endTime,zone,true)}</strong><span>${duration(Math.round((Date.parse(x.endTime)-Date.parse(x.startTime))/60000))}</span></header><details><summary>View route details</summary><div class="transit-steps">${x.legs.map(l=>`<div><strong>${localClock(l.startTime,zone,true)} · ${esc(l.mode)}</strong><span>${esc(l.from?.name||'Start')} → ${esc(l.to?.name||'End')}</span><small>Arrive ${localClock(l.endTime,zone,true)}</small></div>`).join('')}</div></details></section>`).join(''):'<p>No suitable scheduled connections found. Other routes may exist.</p>');}catch(e){return '<p>Schedules unavailable for this direction. Try again later.</p>';}}
 try{const out=await direction(airportCode,flightTime,false);target.innerHTML='<h4>To the airport</h4>'+out;if(returnAirport){const back=await direction(returnAirport,returnTime,true);target.innerHTML+='<h4>From the airport after returning</h4>'+back;}target.innerHTML+='<small>Schedules may change. Airport and city reference points may differ from your exact locations. <a href="https://transitous.org/sources/">Transit data sources</a></small>';}finally{button.disabled=false;}
}

function shortDate(v){const d=new Date(String(v||'').slice(0,10)+'T12:00:00Z');return Number.isFinite(+d)?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(d):'—';}
function airportZone(code){return ({ALB:'America/New_York',JFK:'America/New_York',EWR:'America/New_York',LGA:'America/New_York',BOS:'America/New_York',BDL:'America/New_York',SYR:'America/New_York',PVD:'America/New_York',RUT:'America/New_York',PHL:'America/New_York',BWI:'America/New_York',RDU:'America/New_York',IAD:'America/New_York',DCA:'America/New_York',ATL:'America/New_York',CLT:'America/New_York',GSP:'America/New_York',ORD:'America/Chicago',MDW:'America/Chicago',LAX:'America/Los_Angeles',SFO:'America/Los_Angeles'})[code];}
function localInstant(v,zone){const raw=String(v||'').replace(' ','T');const desired=Date.parse(raw+'Z');if(!Number.isFinite(desired))return NaN;let t=desired;for(let i=0;i<3;i++){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(t).map(p=>[p.type,p.value]));const wall=Date.UTC(+parts.year,+parts.month-1,+parts.day,+parts.hour,+parts.minute,+parts.second);t+=desired-wall;}return t;}
function localClock(v,zone,day=false){const d=new Date(v);return Number.isFinite(+d)?new Intl.DateTimeFormat('en-US',{timeZone:zone,hour:'numeric',minute:'2-digit',...(day?{month:'short',day:'numeric'}:{})}).format(d):'—';}

// Persistent summary stores only display data, never credentials or provider tokens.
const tripStorageKey='roamai.savedTrip.v1';
let savedTrip=null;
function flightSnapshot(f){return {price:f.price,departure:{id:f.departure.id,time:f.departure.time},arrival:{id:f.arrival.id,time:f.arrival.time},airlines:f.airlines||[]};}
function saveTrip(value){savedTrip=value;try{if(value)localStorage.setItem(tripStorageKey,JSON.stringify(value));else localStorage.removeItem(tripStorageKey);$('saveStatus').textContent=value?'Saved on this device':'No saved trip';}catch{$('saveStatus').textContent='Browser storage unavailable; progress is session-only';}renderSavedTrip();}
function renderSavedTrip(){const t=savedTrip;const panel=$('savedTrip');panel.hidden=!t;if(!t)return;const transport=t.transport;const knownGround=Number.isFinite(transport?.cost)?transport.cost:Number.isFinite(transport?.fuel)?transport.fuel+(Number.isFinite(transport.parking)?transport.parking:0):null;const airfare=t.returnFlight?.price??t.flight.price;const verified=t.adults===1;const subtotal=airfare+(knownGround??0)+(t.accommodation?.cost??0)+(t.itinerary?.knownCost??0);const row=(name,detail,price)=>`<div class="saved-row"><div><strong>${esc(name)}</strong><small>${esc(detail)}</small></div><strong>${esc(price)}</strong></div>`;const leg=f=>`${f.departure.id} → ${f.arrival.id} · ${f.departure.time} · ${f.airlines.join(' / ')}`;$('savedContent').innerHTML=`<h3>${esc(t.destination)}</h3><p class="note">${esc(t.origin)} · ${esc(t.outbound)} – ${esc(t.returning)} · ${t.adults} traveler(s)</p>${row('Round-trip flights',t.returnFlight?'Both flights selected':'Return not selected',money(airfare)+' quote')}${row('Outbound',leg(t.flight),'')}${row('Return',t.returnFlight?leg(t.returnFlight):'Not selected','')}${row('Airport transportation',transport?transport.name+' · '+(knownGround===null?'unpriced':transport.low!=null?'estimated fare':transport.parking===null?'parking and tolls unknown':'tolls excluded'):'Not selected',knownGround===null?'—':money(knownGround))}${transport?.fuel!=null?row('Fuel','Round trip',money(transport.fuel))+row('Parking','',transport.parking===null?'Unknown':money(transport.parking))+row('Tolls','','Not included'):''}${transport?.fareOut!=null?row('To airport','Per traveler',money(transport.fareOut))+row('From airport','Per traveler',money(transport.fareBack)):''}${row('Accommodation',t.accommodation?.name||'Not selected',t.accommodation?money(t.accommodation.cost):'—')}${['Destination transportation','Food and dining'].map(n=>row(n,'Not estimated','—')).join('')+row('Activities',t.itinerary?t.itinerary.name+' · '+t.itinerary.unknown+' unpriced':'Not estimated',t.itinerary?money(t.itinerary.knownCost)+' known':'—')}<div class="saved-total"><small>${verified?'Estimated trip cost so far':'Airfare quote · group basis unverified'}</small><strong>${money(verified?subtotal:airfare)}</strong>${verified?`<progress class="${subtotal>t.budget?'over':subtotal>=t.budget*.8?'near':''}" max="100" value="${Math.min(100,subtotal/t.budget*100)}"></progress><small>${money(Math.abs(t.budget-subtotal))} ${subtotal>t.budget?'over budget':'remaining before unpriced expenses'} · ${money(t.budget)} budget</small>`:'<small>Budget remainder withheld until group fare basis is verified.</small>'}</div><p class="note">Saved quotes are not reservations. Prices may change. After reloading, search again to edit flights or transport.</p>`;}
try{const raw=localStorage.getItem(tripStorageKey);if(raw){const t=JSON.parse(raw);if(t&&t.flight?.departure&&t.flight?.arrival&&Array.isArray(t.flight.airlines)&&Number.isFinite(t.budget)&&t.budget>0){savedTrip=t;renderSavedTrip();$('saveStatus').textContent='Saved on this device · previous quote';}}}catch{$('saveStatus').textContent='Saved trip unavailable';}
$('clearSavedTrip').onclick=()=>{if(confirm('Clear your saved trip?'))saveTrip(null);};

