const hotelCache=new Map();
function accommodationStep(panel,token,back){
 const t=savedTrip;if(!t?.returnFlight)return;
 const start=String(t.flight.arrival.time).slice(0,10),end=String(t.returnFlight.departure.time).slice(0,10);
 panel.innerHTML=`<div class="trip-progress">Flights selected → Airport transport selected → Accommodation</div><h3>Find your stay</h3><p class="note">${esc(t.destination)} · ${t.adults} traveler(s)</p><button type="button" data-back>Change airport transportation</button><div class="stay-fields"><label>Destination<input data-city value="${esc(t.destination)}"></label><label>Check-in<input type="date" data-in value="${esc(start)}"></label><label>Check-out<input type="date" data-out value="${esc(end)}"></label><label>Accommodation<select data-type><option value="all">All stays</option><option value="hotel">Hotels</option><option value="hostel">Hostels</option><option value="vacation_rental">Vacation rentals</option></select></label></div><details><summary>Already have accommodation?</summary><label>Total cost for your group ($)<input data-manual type="number" min="0" step="0.01"></label><button type="button" data-apply>Use my accommodation cost</button><button type="button" data-free>No accommodation cost</button></details><button type="button" data-search class="stay-search">Search stays</button><p data-status role="status" class="note"></p><div class="stay-results-layout" data-layout hidden><aside class="filters stay-filters"><h4>Filters</h4><label>Maximum total price ($)<input data-max type="number" min="0" placeholder="Any price"></label><label>Minimum guest rating<select data-rating><option value="0">Any rating</option><option value="3">3+</option><option value="4">4+</option><option value="4.5">4.5+</option></select></label><label>Sort by<select data-sort><option value="price">Lowest price</option><option value="rating">Highest rated</option></select></label><label>Property type<select data-kind><option value="all">All types</option><option value="hotel">Hotels</option><option value="hostel">Hostels</option><option value="vacation_rental">Vacation rentals</option><option value="other">Other</option></select></label><h4>Amenities</h4>${["Free Wi-Fi","Free parking","Free breakfast","Outdoor pool","Kitchen","Air conditioning","Airport shuttle"].map(a=>`<label class="stay-check"><input type="checkbox" data-amenity="${a}"> ${a}</label>`).join("")}<button type="button" data-reset>Reset filters</button></aside><div data-results></div></div><p data-selected role="status"></p>`;
 const next=document.createElement('button');next.type='button';next.className='stay-search';next.textContent='Continue to itinerary';next.hidden=!t.accommodation;panel.append(next);next.onclick=()=>{serial++;itineraryStep(panel,token,()=>accommodationStep(panel,token,back));};
 const q=x=>panel.querySelector('[data-'+x+']');let hotels=[],search=null,serial=0;
 const select=(name,cost,dates,extra={})=>{if(!panel.isConnected||!savedTrip)return;saveTrip({...savedTrip,itinerary:null,accommodation:{name,cost,...dates,...extra}});q('selected').textContent=name+' selected · '+money(cost)+' total. Your trip summary has been updated.'; next.hidden=false;};
 q('back').onclick=()=>{serial++;back();};
 const dates=()=>({check_in:q('in').value,check_out:q('out').value});
 const validDates=()=>{const d=dates();return d.check_in&&d.check_out&&d.check_out>d.check_in;};
 q('apply').onclick=()=>{const x=q('manual');if(x.value!==''&&x.checkValidity()&&validDates())select('Own accommodation',Number(x.value),dates());else q('selected').textContent='Enter valid dates and a total cost.';};
 q('free').onclick=()=>select('No accommodation cost',0,dates());
 const link=v=>{try{const u=new URL(v);return u.protocol==='https:'?esc(u.href):'';}catch{return '';}};
 const render=()=>{const max=q('max').value===''?Infinity:Number(q('max').value),rating=Number(q('rating').value);const list=hotels.filter(h=>(max===Infinity||Number.isFinite(h.total_price)&&h.total_price<=max)&&(!rating||h.rating>=rating)&&(q('kind').value==='all'||h.type===q('kind').value)&&[...panel.querySelectorAll('[data-amenity]:checked')].every(a=>h.amenities?.includes(a.dataset.amenity))).sort((a,b)=>q('sort').value==='rating'?(b.rating??-1)-(a.rating??-1):(a.total_price??Infinity)-(b.total_price??Infinity));const priced=list.filter(h=>Number.isFinite(h.total_price)&&h.total_price>0);const cheapest=[...priced].sort((a,b)=>a.total_price-b.total_price)[0];const rated=[...priced].filter(h=>Number.isFinite(h.rating)).sort((a,b)=>b.rating-a.rating)[0];const value=[...priced].filter(h=>h.rating>=4&&h.reviews>=20).sort((a,b)=>a.total_price-b.total_price)[0];const featured=[...new Set([cheapest,value,rated].filter(Boolean))];const ordered=[...featured,...list.filter(h=>!featured.includes(h))];q('results').innerHTML=(ordered.length?'<p class="note">'+ordered.length+' stays · prices for the requested travelers; confirm room occupancy and final charges.</p>':'<p>No matching stays.</p>')+ordered.map((h,i)=>`<article class="stay-card">${link(h.image)?`<img loading="lazy" src="${link(h.image)}" alt="" referrerpolicy="no-referrer">`:''}<div><small class="stay-tag">${[h===cheapest?'Lowest price':'',h===value?'Lowest price rated 4+':'',h===rated?'Highest rated':''].filter(Boolean).join(' · ')}</small><h4>${esc(h.name)}</h4><small>${esc(h.address||'')} · ${esc((h.type||'Stay').replaceAll('_',' '))}</small><p>${h.rating!=null?'★ '+esc(h.rating)+' / 5 · '+esc(h.reviews??'')+' reviews':'Not rated'}</p><small>${esc((h.amenities||[]).slice(0,5).join(' · '))}</small><p>${link(h.website)?`<a href="${link(h.website)}" target="_blank" rel="noopener noreferrer">Property website</a> · `:''}${link(h.search_url)?`<a href="${link(h.search_url)}" target="_blank" rel="noopener noreferrer">Compare prices</a>`:''}</p></div><div class="stay-price"><small>${Number.isFinite(h.nightly_price)?money(h.nightly_price)+' / night':''}</small><strong>${Number.isFinite(h.total_price)?money(h.total_price):'Price unavailable'}</strong><small>${esc(h.nights)} nights · ${h.price_type==='nightly_estimate'?'Estimated total':'Stay total'}</small><small>${h.taxes_and_fees==='included'?'Taxes and fees included':'Confirm taxes and fees'}</small><button type="button" data-pick="${i}" ${Number.isFinite(h.total_price)&&h.total_price>0?'':'disabled'}>Select stay</button></div></article>`).join('');q('results').querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const h=ordered[+b.dataset.pick];select(h.name,h.total_price,{check_in:search.check_in,check_out:search.check_out},{price_type:h.price_type,taxes_and_fees:h.taxes_and_fees,coordinates:h.coordinates,destination:search.destination});});};
 for(const x of ['max','rating','sort','kind'])q(x).onchange=()=>{if(search)render();};
 panel.querySelectorAll('[data-amenity]').forEach(a=>a.onchange=()=>{if(search)render();});
 q('reset').onclick=()=>{q('max').value='';q('rating').value='0';q('sort').value='price';q('kind').value='all';panel.querySelectorAll('[data-amenity]').forEach(a=>a.checked=false);if(search)render();};
 for(const x of ['city','in','out','type'])q(x).onchange=()=>{serial++;hotels=[];search=null;q('layout').hidden=true;q('results').innerHTML='';q('status').textContent='Search again for updated stays.';q('search').disabled=false;};
 q('search').onclick=async()=>{if(!validDates()||!q('city').value.trim()){q('status').textContent='Enter a destination and valid stay dates.';return;}const id=++serial;const params=new URLSearchParams({destination:q('city').value.trim(),...dates(),adults:String(t.adults),type:q('type').value});const key=params.toString();q('search').disabled=true;q('layout').hidden=true;q('status').textContent='Finding available stays…';q('results').innerHTML='';try{if(!hotelCache.has(key)){const response=await fetch('https://roamai-api.davidjackm2007.workers.dev/hotels?'+key,{headers:{Authorization:'Bearer '+token.trim().replace(/^Bearer\s+/i,'')},signal:AbortSignal.timeout(60000)});const data=await response.json();if(!response.ok||data.status!=='success'||!Array.isArray(data.hotels))throw Error(data.error||'Accommodation search failed');hotelCache.set(key,data);}if(id!==serial||!panel.isConnected)return;const data=hotelCache.get(key);hotels=data.hotels;search=data.search;q('layout').hidden=false;q('status').textContent='Quotes may change before booking.';render();}catch(e){if(id===serial)q('status').textContent=e.message;}finally{if(id===serial)q('search').disabled=false;}};
 if(t.accommodation)q('selected').textContent=t.accommodation.name+' selected · '+money(t.accommodation.cost);
 panel.scrollIntoView({behavior:'smooth'});
}

// V11: itinerary planning, one attraction search shared by all options.
const attractionSession=new Map();
const itineraryInterests=[['nature','Nature & outdoors'],['history,culture','History & culture'],['local_experience','Food & local experiences'],['beach','Beaches & relaxation'],['entertainment','Entertainment'],['nature,entertainment','Adventure'],['local_experience','Shopping'],['sightseeing','Sightseeing']];
const itineraryModes=['Budget Explorer','Balanced Experience','Experience Everything'];
function itineraryDistance(a,b){return km(a,{lat:b.latitude,lon:b.longitude});}
function itineraryCost(a){return Number.isFinite(a.admission_price)&&a.admission_price>=0?a.admission_price:a.admission==='free'?0:null;}
function itineraryDays(t){const start=String(t.flight.arrival.time).slice(0,10),end=String(t.returnFlight.departure.time).slice(0,10);const a=Date.parse(start+'T00:00:00Z'),b=Date.parse(end+'T00:00:00Z');if(!Number.isFinite(a)||!Number.isFinite(b)||b<a||b-a>90*86400000)throw Error('Itinerary supports trips of up to 90 nights.');return Array.from({length:Math.round((b-a)/86400000)+1},(_,i)=>new Date(a+i*86400000).toISOString().slice(0,10));}
function itineraryHours(a,date){return a.opening_hours?.[new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'long',timeZone:'UTC'}).toLowerCase()]||null;}
function itineraryBuild(t,places,center,interests,pace,mode){const days=itineraryDays(t),used=new Set();return days.map((date,i)=>{const edge=i===0||i===days.length-1;const arrival=Number(String(t.flight.arrival.time).slice(11,13)),departure=Number(String(t.returnFlight.departure.time).slice(11,13));let limit=edge?1:({Relaxed:1,Balanced:2,Packed:3}[pace]);if(mode===2&&!edge)limit++;if((i===0&&arrival>=16)||(i===days.length-1&&departure<14)||days.length===1)limit=0;const items=[];let anchor=center;for(let j=0;j<limit;j++){const candidates=places.filter(a=>!used.has(a.id)&&!/^closed$/i.test(itineraryHours(a,date)||'')&&!items.some(b=>itineraryDistance(a.coordinates,b.coordinates)<0.35&&a.category===b.category));const score=a=>{const match=interests.includes(a.category)?5:0, popularity=Math.log10(1+(a.reviews||0)),rating=a.rating||3,dist=itineraryDistance(anchor,a.coordinates),cost=itineraryCost(a),park=/theme park|amusement park/i.test((a.types||[]).join(' '));return match+rating+(mode===2?2:0.7)*popularity-dist*(mode===0?0.65:0.25)+(mode===0?(cost===0?12:cost===null?(park?-9:0):-cost/10):mode===2&&park?5:0);};candidates.sort((a,b)=>score(b)-score(a));const a=candidates[0];if(!a)break;items.push({...a,manualCost:null});used.add(a.id);anchor=a.coordinates;if(/theme park|amusement park/i.test((a.types||[]).join(' ')))break;}return {date,items};});}
function itineraryTotals(days,adults){let knownCost=0,unknown=0;for(const d of days)for(const a of d.items){const c=a.manualCost??itineraryCost(a);if(c===null)unknown++;else knownCost+=c*adults;}return {knownCost,unknown};}
function itineraryStep(panel,token,back){const t=savedTrip;if(!t?.accommodation)return;let active=true,plans=[],pool=[],current=1;const link=v=>{try{const u=new URL(v);return u.protocol==='https:'?esc(u.href):'';}catch{return '';}};panel.innerHTML=`<div class="trip-progress">Flights → Airport transportation → Accommodation → Itinerary</div><h3>Plan your experience</h3><p class="note">${esc(t.destination)} · ${t.adults} traveler(s)</p><button type="button" data-i-back>Change accommodation</button><h4>What would you like to experience?</h4><p class="note">Optional — choose as many as you like.</p><div class="interest-grid">${itineraryInterests.map(([v,n])=>`<label><input type="checkbox" value="${v}"> ${n}</label>`).join('')}</div><label>Preferred travel pace<select data-i-pace><option>Relaxed</option><option selected>Balanced</option><option>Packed</option></select></label><button class="stay-search" data-i-generate>Generate itineraries</button><p class="note" role="status" data-i-status></p><div data-i-results></div>`;const q=n=>panel.querySelector('[data-i-'+n+']');q('back').onclick=()=>{active=false;back();};
function render(){const days=plans[current],tot=itineraryTotals(days,t.adults);q('results').innerHTML=`<div class="itinerary-tabs">${itineraryModes.map((n,i)=>`<button data-mode="${i}" aria-pressed="${i===current}">${n}</button>`).join('')}</div><p class="note">${money(tot.knownCost)} known admission costs for your group · ${tot.unknown} activities unpriced. Food and local transportation excluded. Budget Explorer favors lower-cost candidates, but unknown prices prevent a verified cheapest ranking.</p>${days.map((d,i)=>`<section class="itinerary-day"><h4>Day ${i+1} · ${esc(d.date)}</h4>${d.items.length?d.items.map((a,j)=>`<article class="activity-row">${link(a.image)?`<img src="${link(a.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<div><strong>${esc(a.name)}</strong><p>${esc(a.category.replaceAll('_',' '))} · ${a.rating?'★ '+esc(a.rating):'Not rated'}</p><p>${esc(a.description||a.address||'')}</p><small>${esc(itineraryHours(a,d.date)||'Hours unavailable')} · verify for travel date</small><p>${link(a.website)?`<a href="${link(a.website)}" target="_blank" rel="noopener noreferrer">Website</a> · `:''}${link(a.map_url)?`<a href="${link(a.map_url)}" target="_blank" rel="noopener noreferrer">Map</a>`:''}</p><label>Admission per traveler ($)<input type="number" min="0" step="0.01" data-price="${i},${j}" value="${a.manualCost??itineraryCost(a)??''}" placeholder="Unknown"></label><div class="activity-actions"><button data-remove="${i},${j}">Remove</button><select data-swap="${i},${j}" aria-label="Swap activity"><option value="">Swap activity…</option>${pool.filter(b=>!days.some(x=>x.items.some(y=>y.id===b.id))&&!/^closed$/i.test(itineraryHours(b,d.date)||'')).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')}</select></div></div></article>`).join(''):'<p class="note">Open time for travel, rest or independent exploration.</p>'}</section>`).join('')}<button class="stay-search" data-i-save>Select this itinerary</button><p class="note" data-i-saved></p>`;q('results').querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{current=+b.dataset.mode;render();});for(const kind of ['remove','swap','price'])q('results').querySelectorAll('[data-'+kind+']').forEach(el=>{const handler=()=>{const [i,j]=el.dataset[kind].split(',').map(Number);if(kind==='remove')days[i].items.splice(j,1);else if(kind==='swap'){const a=pool.find(a=>a.id===el.value);if(!a)return;days[i].items[j]={...a,manualCost:null};}else{if(!el.checkValidity())return;days[i].items[j].manualCost=el.value===''?null:Number(el.value);}render();};if(kind==='remove')el.onclick=handler;else el.onchange=handler;});q('save').onclick=()=>{if(savedTrip!==t&&savedTrip?.accommodation!==t.accommodation)return;saveTrip({...savedTrip,itinerary:{name:itineraryModes[current],days:days.map(d=>({date:d.date,items:d.items.map(a=>({id:a.id,name:a.name,coordinates:a.coordinates,manualCost:a.manualCost,admission_price:a.admission_price,admission:a.admission}))})),...tot}});q('saved').textContent='Itinerary saved to your trip summary. Destination transportation is next in V12.';};}
q('generate').onclick=async()=>{q('generate').disabled=true;q('status').textContent='Finding attractions…';try{const destination=t.accommodation.destination||t.destination;const matches=await places(destination);const city=matches.find(x=>normalize(placeLabel(x))===normalize(destination))|| (matches.length===1?matches[0]:null);const hotel=t.accommodation.coordinates;const center=city?{latitude:city.latitude,longitude:city.longitude}:hotel;if(!center||!Number.isFinite(center.latitude)||!Number.isFinite(center.longitude))throw Error('Choose a specific destination city from the search suggestions.');const params=new URLSearchParams({destination,lat:String(center.latitude),lon:String(center.longitude),radius:'30000'});const key=params.toString();if(!attractionSession.has(key)){const r=await fetch('https://roamai-api.davidjackm2007.workers.dev/attractions?'+key,{headers:{Authorization:'Bearer '+token.trim().replace(/^Bearer\s+/i,'')},signal:AbortSignal.timeout(60000)});const data=await r.json();if(!r.ok||data.status!=='success'||!Array.isArray(data.attractions))throw Error(data.error||'Attraction search failed');attractionSession.set(key,data.attractions);}if(!active||!panel.isConnected)return;pool=attractionSession.get(key).filter(a=>a.id&&a.name&&Number.isFinite(a.coordinates?.latitude)&&Number.isFinite(a.coordinates?.longitude));const interests=[...panel.querySelectorAll('.interest-grid input:checked')].flatMap(x=>x.value.split(','));plans=itineraryModes.map((_,i)=>itineraryBuild(t,pool,hotel&&Number.isFinite(hotel.latitude)&&Number.isFinite(hotel.longitude)?hotel:center,interests,q('pace').value,i));q('status').textContent=pool.length+' attractions found · suggested plans, not confirmed reservations. Open days are intentional when results are limited.';render();}catch(e){if(active)q('status').textContent=e.message;}finally{if(active)q('generate').disabled=false;}};panel.scrollIntoView({behavior:'smooth'});}
